namespace cold=mgscoop::carry_cold_rollback;
namespace abortq=mgscoop::carry_queued_abort;
unsigned good=0,bad=0;void Check(bool x,const char* name){if(x)++good;else{++bad;std::printf("FAIL %s\n",name);}}
constexpr std::uintptr_t Image=0x140000000;constexpr std::size_t Span=0xa01d000;
cold::Scope Fixture(unsigned carrier=0){cold::Scope s{};auto& q=s.end.fresh;auto& l=q.expected.lease;l.mission=30050;l.generation=3;l.thread=9;l.transaction=5;l.revision=7;l.epoch=2;l.carrier=static_cast<std::uint8_t>(carrier);l.recipient=static_cast<std::uint8_t>(1-carrier);l.cause=1;l.player=0x10000;l.carrierRecord=0x70000+carrier*0x1000;l.recipientPhase=0xd0030+(1-carrier)*0x1000;
 q.expected.queue=0x20000;q.expected.array=0x40000;q.expected.slot=q.expected.array+l.recipient*0x40;q.current=q.expected;q.priorSequence=q.committedSequence=0x10;
 q.exactGate=q.serializedNaturalWindow=q.typedAllocation=q.coherentNativeStates=q.deferredQueueQuiesced=q.controlsRetained=true;
 mgscoop::carry_request_payload::BuildRecipient(Image,Span,carrier,1-carrier,q.priorSequence,q.ours);q.ours.force=0;q.observed=q.ours;q.carrierActive=true;q.carrierCurrent=q.carrierNext=1;q.carrierProgress=2;q.carrierOfflineOwned=1;q.carrierVariant=0xa;q.carrierOwner=l.carrier;q.carrierTarget=q.carrierPrevious=l.recipient;
 s.end.serializedCarrierWindow=true;q.windowBody=l.carrier;
 s.initial.record=s.current.record=l.carrierRecord;s.initial.vtable=s.current.vtable=Image+0x23b9468;s.initial.playerFlags=s.current.playerFlags=1;s.current.closureCallback=Image+0x113bba0;
 s.exactColdGate=s.typedColdReads=s.coherentColdReads=s.deferredAndNativeMutationQuiesced=true;return s;
}
int main(){auto s=Fixture();abortq::Token t{};abortq::NeutralRequest n{};Check(cold::Check(Image,Span,s)==cold::Reason::end_unqualified,"cold fields alone never qualify End");Check(!cold::Nominate(Image,Span,s,t),"no native permission by branch exclusions");
 for(unsigned role=0;role<2;++role){s=Fixture(role);auto& q=s.end.fresh;q.windowBody=q.expected.lease.recipient;t={};Check(abortq::Plan(Image,Span,q,t,n)==abortq::Reason::plan,"recipient neutral plan");Check(abortq::Confirm(Image,Span,q,n,t),"neutral readback before carrier nomination");q.windowBody=q.expected.lease.carrier;s.end.readback=n;s.end.fullyQualifiedEnd=true;Check(cold::Nominate(Image,Span,s,t),"separate full qualification plus cold branches allow nomination");Check(!cold::Nominate(Image,Span,s,t),"one nomination per lease");}
 for(auto member:{&cold::Scope::exactColdGate,&cold::Scope::typedColdReads,&cold::Scope::coherentColdReads,&cold::Scope::deferredAndNativeMutationQuiesced}){s=Fixture();s.*member=false;Check(cold::Check(Image,Span,s)==cold::Reason::scope,"missing independent cold proof refuses");}
 for(unsigned k=0;k<6;++k){s=Fixture();switch(k){case 0:s.initial.record+=8;break;case 1:s.current.record+=8;break;case 2:s.initial.vtable+=8;break;case 3:s.current.vtable+=8;break;case 4:s.end.fresh.expected.lease.carrierRecord=0;break;default:s.current.record=0;break;}Check(cold::Check(Image,Span,s)==cold::Reason::identity,"typed carrier cold record cannot be replaced");}
 for(unsigned fresh=0;fresh<2;++fresh)for(unsigned k=0;k<4;++k){s=Fixture();auto& a=fresh?s.current:s.initial;switch(k){case 0:a.resourceKind=4;break;case 1:a.resource248=0x1234;break;case 2:a.resource250=0x1234;break;default:a.resource258=0x1234;break;}Check(cold::Check(Image,Span,s)==cold::Reason::resources,"initial and fresh resource dependencies must remain absent");}
 for(unsigned fresh=0;fresh<2;++fresh)for(unsigned k=0;k<5;++k){s=Fixture();auto& a=fresh?s.current:s.initial;switch(k){case 0:a.playerFlags=0;break;case 1:a.playerFlags|=0x100;break;case 2:a.flags6A6|=0x1000;break;case 3:a.dropFlags27D=1;break;default:a.dropFlags27D=2;break;}Check(cold::Check(Image,Span,s)==cold::Reason::drop,"producer or preexisting drop flag prevents exclusion");}
 s=Fixture();s.current.flags6A6=0x800;Check(cold::DropBranchesExcluded(s.current),"800 alone cannot set27D;1000 is the branch guard");s.current.flags6A6|=0x1000;Check(!cold::DropBranchesExcluded(s.current),"1000 plus800 reaches stored-position drop");s=Fixture();s.current.closureCallback=Image+0x1138a00;Check(cold::Check(Image,Span,s)==cold::Reason::closure,"only current initial forced-A closure eligible");s=Fixture();s.current.closureThisAdjust=0x10;Check(cold::Check(Image,Span,s)==cold::Reason::closure,"foreign adjusted closure refused");s=Fixture();Check(cold::Check(Image,0x1000,s)==cold::Reason::identity,"short exact image refused");for(std::size_t available=0;available<sizeof(std::uintptr_t);++available){s=Fixture();Check(cold::Check(Image,0x23b9468+available,s)==cold::Reason::identity,"cut-off final record vtable identity refused");}s=Fixture();Check(cold::Check(Image,0x23b9468+sizeof(std::uintptr_t),s)==cold::Reason::end_unqualified,"exact identity extent still does not qualify End or full code gate");Check(cold::Check(UINTPTR_MAX-7,Span,s)==cold::Reason::identity,"overflow image refused");std::printf("%u passed, %u failed\n",good,bad);return bad?1:0;}
